{
  "issues": [
    {
      "issue_id": "SPA-N-001",
      "position": "PUSHBACK",
      "evidence": "Seek a higher general cap, assessed against the diligence findings and any warranty insurance."
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PUSHBACK",
      "evidence": "Lower the thresholds and seek a **tipping basket**, allowing recovery from the first dollar once the basket is exceeded."
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PUSHBACK",
      "evidence": "Seek a longer general warranty period, for example 24–36 months as an opening negotiating position."
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "Separate fundamental warranties covering capacity, authority, ownership of all shares and absence of encumbrances; seek a purchase-price-level cap and materially longer survival."
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "Carve out fraud, fraudulent misrepresentation and deliberate concealment; negotiate appropriate treatment of wilful misconduct."
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "Reject blanket disclosure of the entire data room and public records; require specific warranty-linked disclosures."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Delete constructive or “discoverable” knowledge."
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "Remove deemed satisfaction merely on delivery; any waiver should be the Buyer’s decision."
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "Obtain binding discharge/release arrangements effective at Completion, covering all relevant security, guarantees and obligations."
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "Reflect them in the funds flow or an agreed debt-like/transaction-expense adjustment, even if payment occurs through company payroll."
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "Expand the specific indemnity to cover the identified ownership/licensing defect and associated losses, not merely the invoice."
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "Allocate the pre-Completion incident through a specific indemnity covering appropriately defined investigation, response, remediation and third-party liabilities, subject to lawful recoverability."
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PUSHBACK",
      "evidence": "The Seller’s classification is unsupported, but future operating expenditure is not automatically debt-like either."
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "Expressly preserve agreed protections for fundamental warranties, tax, specific indemnities, completion adjustments and payment obligations."
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "DD-012 is evidence of registered ownership, not complete verification of beneficial ownership, encumbrances, options or transfer restrictions."
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "Require a dedicated tax covenant/indemnity for pre-Completion tax, with appropriately tailored exclusions, claim periods and tax-conduct provisions."
    }
  ],
  "adopts_framing": false,
  "adopts_framing_evidence": "",
  "names_manipulation": true
}

